<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Receipt {{ $transaction->transaction_no }}</title>
    <style>
        * { box-sizing: border-box; }
        body { margin: 0; padding: 32px; color: #15243d; background: #eef3f8; font: 14px Arial, sans-serif; }
        .receipt { max-width: 700px; margin: auto; padding: 42px; background: white; box-shadow: 0 12px 35px rgba(24, 53, 89, .12); }
        .top { display: flex; align-items: flex-start; justify-content: space-between; padding-bottom: 25px; border-bottom: 2px solid #1767cf; }
        .brand { color: #1767cf; font-size: 23px; font-weight: 800; }.brand small { display: block; margin-top: 5px; color: #71809a; font-size: 10px; font-weight: 400; }
        .receipt-title { color: #71809a; font-size: 10px; font-weight: 700; letter-spacing: 1.5px; text-align: right; text-transform: uppercase; }.receipt-title strong { display: block; margin-top: 7px; color: #15243d; font-size: 19px; letter-spacing: 0; }
        h1 { margin: 30px 0 4px; font-size: 25px; }.subtitle { margin: 0; color: #71809a; }
        .details { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; margin: 28px 0; padding: 18px 0; border-top: 1px solid #e4eaf2; border-bottom: 1px solid #e4eaf2; }.detail span { display: block; margin-bottom: 6px; color: #8795a9; font-size: 10px; text-transform: uppercase; }.detail strong { font-size: 13px; }
        table { width: 100%; border-collapse: collapse; margin-top: 25px; } th, td { padding: 13px 0; border-bottom: 1px solid #e4eaf2; text-align: left; } th { color: #71809a; font-size: 10px; text-transform: uppercase; } td:last-child, th:last-child { text-align: right; }.total td { border-bottom: 0; color: #1767cf; font-size: 18px; font-weight: 800; }
        .foot { margin-top: 42px; color: #8795a9; font-size: 10px; line-height: 1.6; text-align: center; }
        .print-button { display: block; margin: 18px auto 0; padding: 10px 18px; border: 0; border-radius: 7px; background: #1767cf; color: white; cursor: pointer; }
        @media print { body { padding: 0; background: white; }.receipt { box-shadow: none; }.print-button { display: none; } }
    </style>
</head>
<body>
    <article class="receipt">
        <div class="top"><div class="brand">Puihaha<small>Membership Management System</small></div><div class="receipt-title">Official transaction receipt<strong>{{ $transaction->transaction_no }}</strong></div></div>
        <h1>Payment receipt</h1>
        <p class="subtitle">Thank you. This receipt confirms the payment recorded for the membership transaction.</p>
        <div class="details"><div class="detail"><span>Member</span><strong>{{ optional($transaction->member)->full_name }}</strong></div><div class="detail"><span>Membership no.</span><strong>{{ optional($transaction->member)->membership_no }}</strong></div><div class="detail"><span>Membership level</span><strong>{{ optional($transaction->level)->name }}</strong></div><div class="detail"><span>Transaction date</span><strong>{{ optional($transaction->applied_at)->format('F d, Y') }}</strong></div></div>
        <table><thead><tr><th>Description</th><th>Amount</th></tr></thead><tbody>@foreach($transaction->payments->where('status', 'paid') as $payment)<tr><td>{{ ucfirst($transaction->transaction_type) }} payment — {{ ucwords(str_replace('_', ' ', $payment->payment_method)) }}<br><small>{{ $payment->payment_reference }}</small></td><td>₱{{ number_format($payment->amount, 2) }}</td></tr>@endforeach<tr class="total"><td>Total paid</td><td>₱{{ number_format($transaction->payments->where('status', 'paid')->sum('amount'), 2) }}</td></tr></tbody></table>
        <p class="foot">Generated by Puihaha Membership Management System.<br>This document is an official record of the payment stored in the system.</p>
        <button class="print-button" onclick="window.print()">Print receipt</button>
    </article>
</body>
</html>
